758	/* ── Wake-word matching ────────────────────────────────────── */
759	
760	/* Variant table for "你好" / "openvela" wake words.
761	 * ASR often mis-recognizes the non-dictionary word "openvea",
762	 * so common mis-recognition variants are all accepted. */
763	static const char* const WAKE_WORDS[] = {
764	    "你好",
765	    "openvela",
766	    "openvea",
767	    "openvila",
768	    "openwela",
769	    "openvella",
770	    "欧鹏vela",
771	    "opengvela",
772	};
773	
774	/* Normalize ASR text (strip spaces/punctuation, lowercase ASCII)
775	 * then substring-match against the wake-word variant table. */
776	static bool wake_word_match(const char* asr_text)
777	{
778	    char norm[512];
779	    size_t w = 0;
780	    const unsigned char* r = (const unsigned char*)asr_text;
781	
782	    while (*r && w < sizeof(norm) - 1) {
783	        if (*r < 0x80) {
784	            /* Keep only alphanumerics, lowercased; drop space/punct */
785	            if (isalnum(*r)) {
786	                norm[w++] = (char)tolower(*r);
787	            }
788	            r++;
789	            continue;
790	        }
791	        /* Skip common CJK/full-width punctuation (3-byte UTF-8):
792	         * U+3000-3FFF (0xE3 ..), U+FF00-FFEF (0xEF ..),
793	         * U+2000-206F general punct (0xE2 0x80 ..) */
794	        if ((r[0] == 0xE3 || r[0] == 0xEF
795	             || (r[0] == 0xE2 && r[1] == 0x80))
796	            && r[1] != '\0' && r[2] != '\0') {
797	            r += 3;
798	            continue;
799	        }
800	        norm[w++] = (char)*r++;
801	    }
802	    norm[w] = '\0';
803	
804	    for (size_t i = 0; i < sizeof(WAKE_WORDS) / sizeof(WAKE_WORDS[0]); i++) {
805	        if (strstr(norm, WAKE_WORDS[i]) != NULL) {
806	            syslog(LOG_INFO, "[%s] wake word hit: \"%s\" (norm=\"%s\")\n", TAG,
807	                WAKE_WORDS[i], norm);
808	            return true;
809	        }
810	    }
811	    return false;
812	}
