864	/* Downmix stereo → mono: extract left channel from interleaved samples.
865	 * I2S HW requires 2ch, but volc ASR expects 1ch @ 16kHz/16bit.
866	 * Returns mono byte count (= stereo bytes / 2). */
867	static size_t downmix_stereo_to_mono(const uint8_t* stereo, size_t stereo_len,
868	    uint8_t* mono, size_t mono_cap)
869	{
870	    const int16_t* src = (const int16_t*)stereo;
871	    int16_t* dst = (int16_t*)mono;
872	    size_t frames = stereo_len / (2 * sizeof(int16_t)); /* L+R pairs */
873	    if (frames > mono_cap / sizeof(int16_t)) frames = mono_cap / sizeof(int16_t);
874	    for (size_t i = 0; i < frames; i++) {
875	        /* Average L+R — uses both mics (ES7210 ADC1+ADC2) */
876	        int32_t sum = (int32_t)src[i * 2] + (int32_t)src[i * 2 + 1];
877	        dst[i] = (int16_t)(sum / 2);
878	    }
879	    return frames * sizeof(int16_t);
880	}
