1369	int voice_channel_stop(void)
1370	{
1371	    pthread_mutex_lock(&s_voice.lock);
1372	    if (s_voice.state == VOICE_IDLE) {
1373	        pthread_mutex_unlock(&s_voice.lock);
1374	        return -EINVAL;
1375	    }
1376	
1377	    syslog(LOG_INFO, "[%s] stopping conversation (state=%d)\n",
1378	        TAG, s_voice.state);
1379	
1380	    s_voice.conv_running = false;
1381	    s_voice.state = VOICE_IDLE;
1382	
1383	    /* Abort TTS if active */
1384	    s_voice.tts_abort = 1;
1385	    if (s_voice.tts_pb) {
1386	        audio_playback_stop(s_voice.tts_pb);
1387	    }
1388	
1389	    /* Close capture to unblock read() in conversation thread */
1390	    if (s_voice.cap_fd >= 0) {
1391	        capture_close(s_voice.cap_fd);
1392	        s_voice.cap_fd = -1;
1393	    }
1394	    pthread_mutex_unlock(&s_voice.lock);
1395	
1396	    /* Wait for conversation thread to finish */
1397	    pthread_join(s_voice.conv_thread, NULL);
1398	
1399	    syslog(LOG_INFO, "[%s] stopped\n", TAG);
1400	    return 0;
1401	}
