37	/* Non-NULL sentinel handed back as the stream handle: the real state
38	 * lives in volc_e2e_conn.c because a single session serves the whole
39	 * device. */
40	static int s_stream_token;
41	
42	static int e2e_asr_init(void)
43	{
44	    /* Credentials only; the connection is established lazily on the
45	     * first turn so that boot time is unaffected. */
46	    return volc_e2e_load_config();
47	}
