54	static int e2e_stream_open(void** handle)
55	{
56	    if (!handle) return -EINVAL;
57	    *handle = NULL;
58	
59	    int ret = volc_e2e_start();
60	    if (ret == -EAGAIN) {
61	        /* Session is coming up (or backing off after a failure); give it
62	         * a short grace period before giving up on this turn. */
63	        for (int i = 0; i < 50 && !volc_e2e_is_up(); i++) {
64	            usleep(100000);
65	        }
66	        ret = volc_e2e_is_up() ? 0 : -EAGAIN;
67	    }
68	    if (ret != 0) {
69	        syslog(LOG_ERR, "[%s] session unavailable: %d\n", TAG, ret);
70	        return ret;
71	    }
72	
73	    volc_e2e_arm_turn();
74	    *handle = &s_stream_token;
75	    return 0;
76	}
