84	static int e2e_stream_try_recv(void* handle, char* text_out, size_t text_cap)
85	{
86	    if (!handle) return -EINVAL;
87	    return volc_e2e_pop_asr(text_out, text_cap);
88	}
89	
90	static int e2e_stream_finish(void* handle, char* text_out, size_t text_cap)
91	{
92	    if (!handle) return -EINVAL;
93	    if (text_out && text_cap > 0) text_out[0] = '\0';
94	
95	    /* Server side VAD already closed the utterance; whatever is pending
96	     * is returned, otherwise the caller gets an empty string.  The
97	     * session itself stays connected for the next turn. */
98	    int ret = volc_e2e_pop_asr(text_out, text_cap);
99	    volc_e2e_end_turn();
100	    return ret > 0 ? 0 : (ret < 0 ? ret : 0);
101	}
