103	static void e2e_stream_abort(void* handle)
104	{
105	    (void)handle;
106	    /* Not a hard abort of the session: voice_channel.c also lands here
107	     * after a perfectly normal turn.  Only the uplink is closed; the TTS
108	     * channel claimed on ASREnded must survive for the reply. */
109	    volc_e2e_end_turn();
110	}
