112	/* Batch recognition: run the streaming path once so callers that only
113	 * use voice_asr_recognize() (tools, tests) still work. */
114	static int e2e_recognize(const unsigned char* pcm_data, size_t pcm_len,
115	    char* text_out, size_t text_cap)
116	{
117	    if (!pcm_data || pcm_len == 0 || !text_out || text_cap == 0) {
118	        return -EINVAL;
119	    }
120	    text_out[0] = '\0';
121	
122	    void* h = NULL;
123	    int ret = e2e_stream_open(&h);
124	    if (ret != 0) return ret;
125	
126	    const size_t chunk = 640; /* 20ms @16k mono 16bit */
127	    for (size_t off = 0; off < pcm_len; off += chunk) {
128	        size_t n = pcm_len - off;
129	        if (n > chunk) n = chunk;
130	        ret = e2e_stream_send(h, pcm_data + off, n);
