1045	static void handle_asr_ended(void)
1046	{
1047	    syslog(LOG_INFO, "[%s] ASREnded\n", TAG);
1048	
1049	    /* Uplink is closed for this turn. */
1050	    ring_clear(&s_audio_ring);
1051	
1052	    if (s_turn != E2E_TURN_LISTENING) {
1053	        /* The turn was already given up locally (capture timeout, no
1054	         * speech) or a reply is in flight.  Whatever the server
1055	         * synthesizes on its own is accepted as the reply unless our
1056	         * LLM has already produced text (see recv_thread). */
1057	        syslog(LOG_INFO, "[%s] ASREnded ignored (turn=%d)\n",
1058	            TAG, (int)s_turn);
1059	        return;
1060	    }
1061	
1062	    /* Do NOT send {start:true, content:""} here.  The server treats
1063	     * an empty start frame as "our text for this turn is empty" and
1064	     * closes the synthesis pipeline; any subsequent ChatTTSText with
1065	     * real content is then silently ignored.  Instead, let the
1066	     * server's own self-chat play through, and replace it later in
1067	     * volc_e2e_tts_text() once our LLM produces text. */
1068	    s_turn = E2E_TURN_ASR_DONE;
1069	
1070	    /* Hybrid orchestration: enter PENDING so the server's self-chat
1071	     * audio flows into the PCM ring (≈8s of capacity) while the
1072	     * client agent LLM runs in parallel.  The agent will decide
1073	     * later whether to drain the ring (E2E fast path) or discard
1074	     * it (agent path with volc_tts_ws). */
1075	    if (s_hybrid_enabled) {
1076	        s_hybrid = E2E_HYBRID_PENDING;
1077	        s_pcm_abort = false;
1078	        syslog(LOG_INFO, "[%s] hybrid=PENDING (buffering server audio)\n",
1079	            TAG);
1080	    }
1081	
1082	    pthread_mutex_lock(&s_asr_lock);
1083	    s_asr_final = true;
1084	    pthread_mutex_unlock(&s_asr_lock);
1085	}
