1793	int volc_e2e_tts_text(const char* utf8)
1794	{
1795	    if (!utf8 || !utf8[0]) return 0;
1796	    if (!s_running || !s_session_up) return -ENOTCONN;
1797	
1798	    /* Send the empty claim frame {start:true, content:""} FIRST.
1799	     * The server needs this explicit signal to know "this turn's
1800	     * reply will be supplied by the client"; without it, the server
1801	     * treats our subsequent text as a continuation of its own
1802	     * self-chat and NEVER synthesizes it separately.
1803	     *
1804	     * Combined frames like {start:true, content:"text"} do NOT work
1805	     * — the logs show only 1 TTSEnded and ~30KB of "our" audio that
1806	     * is actually the tail of the server's self-chat.
1807	     *
1808	     * Two-frame flow ({start:true, content:""} then {content:"text"})
1809	     * produces 2 TTSEndeds: the server synthesizes our text as a
1810	     * separate stream. */
1811	    int ret = volc_e2e_tts_begin();
1812	    if (ret != 0) return ret;
1813	
1814	    if (s_turn < E2E_TURN_TTS_STREAMING) {
1815	        /* Opening the gate.  Do NOT clear the PCM ring here: the
1816	         * server's self-chat audio is already flowing and must be
1817	         * played in full before our text's audio starts.  Clearing
1818	         * the ring mid-stream would drop the self-chat and mix the
1819	         * tail with our audio, producing a garbled output. */
1820	        s_pcm_eos = false;
1821	        s_pcm_abort = false;
1822	        s_turn = E2E_TURN_TTS_STREAMING;
1823	    }
1824	    s_our_text_sent = true;
1825	    s_our_text_open = true;
1826	
1827	    char* json = build_chat_tts_text(false, utf8, false);
1828	    if (!json) return -ENOMEM;
1829	    return ctrl_push(EVENT_CHAT_TTS_TEXT, json);
1830	}
