1832	int volc_e2e_tts_end(void)
1833	{
1834	    if (!s_running || !s_session_up) return -ENOTCONN;
1835	    if (s_turn < E2E_TURN_TTS_CLAIMED) return 0;
1836	
1837	    /* Close our text stream so late-arriving TTSResponse frames from
1838	     * the server's own self-chat are no longer accepted as ours. */
1839	    s_our_text_open = false;
1840	
1841	    char* json = build_chat_tts_text(false, NULL, true);
1842	    if (!json) return -ENOMEM;
1843	    return ctrl_push(EVENT_CHAT_TTS_TEXT, json);
1844	}
