1846	int volc_e2e_tts_pop_pcm(unsigned char* buf, size_t cap,
1847	    size_t* out_len, int* is_last, int timeout_ms)
1848	{
1849	    if (!buf || cap == 0 || !out_len || !is_last) return -EINVAL;
1850	
1851	    *out_len = 0;
1852	    *is_last = 0;
1853	
1854	    if (!s_pcm_ring.buf) return -ENOTCONN;
1855	
1856	    uint32_t deadline = now_ms() + (uint32_t)(timeout_ms > 0 ? timeout_ms : 0);
1857	
1858	    for (;;) {
1859	        if (s_pcm_abort) return -ECANCELED;
1860	
1861	        size_t n = ring_read(&s_pcm_ring, buf, cap);
1862	        if (n > 0) {
1863	            *out_len = n;
1864	            if (s_pcm_eos && ring_count(&s_pcm_ring) == 0) *is_last = 1;
1865	            return 0;
1866	        }
1867	
1868	        if (s_pcm_eos) {
1869	            *is_last = 1;
1870	            return 0;
1871	        }
1872	        if (!s_running) return -ENOTCONN;
1873	        if ((int32_t)(now_ms() - deadline) >= 0) return -ETIMEDOUT;
1874	        usleep(5000);
1875	    }
1876	}
