1909	{
1910	    if (s_hybrid != E2E_HYBRID_PENDING) {
1911	        syslog(LOG_WARNING,
1912	            "[%s] route_e2e: not in PENDING (hybrid=%d turn=%d)\n",
1913	            TAG, (int)s_hybrid, (int)s_turn);
1914	        return -EAGAIN;
1915	    }
1916	
1917	    /* Transition to E2E fast path:
1918	     *   - Set s_hybrid = E2E so volc_e2e_tts knows to drain the ring
1919	     *   - Keep s_pcm_abort = false so pop_pcm can read the ring
1920	     *   - Keep s_pcm_eos as set by TTSEnded (pop_pcm uses it to
1921	     *     return is_last=1 after draining)
1922	     *   - Advance s_turn to TTS_STREAMING so pop_pcm's accept gate
1923	     *     (already open in ASR_DONE) remains open */
1924	    s_hybrid = E2E_HYBRID_E2E;
1925	    s_turn = E2E_TURN_TTS_STREAMING;
1926	
1927	    size_t buffered = ring_count(&s_pcm_ring);
1928	    syslog(LOG_INFO,
1929	        "[%s] hybrid_route=e2e (buffered %zu bytes, eos=%d)\n",
1930	        TAG, buffered, (int)s_pcm_eos);
1931	
1932	    /* If no audio at all (server silent), mark abort so consumer
1933	     * does not block on pop_pcm waiting for data that will never
1934	     * arrive.  The reply will fall back to the error path. */
1935	    if (buffered == 0 && s_pcm_eos) {
1936	        syslog(LOG_WARNING,
1937	            "[%s] hybrid_route=e2e: no server audio available\n", TAG);
1938	        return 0;  /* Caller will pop_pcm and get is_last=1 immediately */
1939	    }
1940	    return 0;
1941	}
