802	static int send_audio_frame(const unsigned char* audio, size_t alen)
803	{
804	    if (!s_tls_valid || s_session_id[0] == '\0') return -ENOTCONN;
805	
806	    size_t sid_len = strlen(s_session_id);
807	    size_t frame_len = VOLC_HDR_SIZE + 4 + 4 + sid_len + 4 + alen;
808	    unsigned char* frame = malloc(frame_len);
809	    if (!frame) return -ENOMEM;
810	
811	    size_t off = 0;
812	    frame[off++] = VOLC_PROTO_VER;
813	    frame[off++] = VOLC_MSG_AUDIO_REQ | VOLC_FLAG_EVENT;
814	    frame[off++] = VOLC_SER_RAW;
815	    frame[off++] = 0x00;
816	
817	    write_be32(frame, off, EVENT_TASK_REQUEST);
818	    off += 4;
819	    write_be32(frame, off, (uint32_t)sid_len);
820	    off += 4;
821	    memcpy(frame + off, s_session_id, sid_len);
822	    off += sid_len;
823	    write_be32(frame, off, (uint32_t)alen);
824	    off += 4;
825	    memcpy(frame + off, audio, alen);
826	
827	    int ret = ws_send_masked(&s_tls, WS_OPCODE_BINARY, frame, frame_len);
828	    free(frame);
829	    return ret;
830	}
